package service

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// Cross-language parity gate (#1094). The fixture is generated by the PHP
// implementation and committed to BOTH repos; if either side's encoding drifts
// by one byte, this test fails here and its twin fails in backend/ — before a
// device can sign something Cloud would reject.
//
// Keep testdata/offline_signing_golden.json byte-identical to
// backend/tests/Fixtures/offline_signing_golden.json.

type goldenFixture struct {
	Version string `json:"version"`
	Cases   []struct {
		Name      string           `json:"name"`
		Selection OfflineSelection `json:"selection"`
		Envelope  struct {
			DeviceID        string `json:"device_id"`
			IssuerID        string `json:"issuer_id"`
			CatalogRevision int    `json:"catalog_revision"`
			IssuedAt        string `json:"issued_at"`
			ExpiresAt       string `json:"expires_at"`
			KeyID           string `json:"key_id"`
		} `json:"envelope"`
		ExpectedSelectionDigest string `json:"expected_selection_digest"`
		ExpectedMessageSHA256   string `json:"expected_message_sha256"`
	} `json:"cases"`
}

func loadGolden(t *testing.T) goldenFixture {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "offline_signing_golden.json"))
	if err != nil {
		t.Fatalf("read golden fixture: %v", err)
	}
	var fx goldenFixture
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatalf("decode golden fixture: %v", err)
	}
	if len(fx.Cases) == 0 {
		t.Fatal("golden fixture has no cases — a silently empty parity gate is worse than none")
	}

	return fx
}

// TestOfflineSigning_GoldenParity — Go must reproduce PHP's digest and message
// byte for byte for every fixture case.
func TestOfflineSigning_GoldenParity(t *testing.T) {
	fx := loadGolden(t)

	if fx.Version != offlineSigningVersion {
		t.Fatalf("signing version drift: fixture %q, Go %q — a version mismatch invalidates every fleet signature",
			fx.Version, offlineSigningVersion)
	}

	for _, c := range fx.Cases {
		t.Run(c.Name, func(t *testing.T) {
			digest := OfflineSelectionDigest(c.Selection)
			if digest != c.ExpectedSelectionDigest {
				t.Errorf("selection digest drift\n Go:  %s\n PHP: %s", digest, c.ExpectedSelectionDigest)
			}

			env := OfflineEvidenceEnvelope{
				DeviceID:        c.Envelope.DeviceID,
				IssuerID:        c.Envelope.IssuerID,
				CatalogRevision: c.Envelope.CatalogRevision,
				IssuedAt:        c.Envelope.IssuedAt,
				ExpiresAt:       c.Envelope.ExpiresAt,
				KeyID:           c.Envelope.KeyID,
			}
			sum := sha256.Sum256([]byte(OfflineSigningMessage(env, digest)))
			if got := hex.EncodeToString(sum[:]); got != c.ExpectedMessageSHA256 {
				t.Errorf("signing message drift\n Go:  %s\n PHP: %s", got, c.ExpectedMessageSHA256)
			}
		})
	}
}

// TestOfflineSigning_DigestIsSensitive — every field that can change what the
// customer ordered must change the digest. A digest that ignores a field is a
// field an attacker can rewrite after the signature.
func TestOfflineSigning_DigestIsSensitive(t *testing.T) {
	str := func(s string) *string { return &s }
	num := func(n int) *int { return &n }

	base := OfflineSelection{
		Lines: []OfflineSelectionLine{{
			LineID:       "line-1",
			ProductSkuID: str("sku-1"),
			Quantity:     1,
			Toppings: []OfflineSelectionTopping{
				{ToppingGroupItemID: "tg-1", ProductSkuID: "sku-t", Quantity: 1},
			},
		}},
		OrderType:  "dine_in",
		PickupType: "immediate",
		Locale:     "ja",
		Channel:    "workstation",
	}
	baseDigest := OfflineSelectionDigest(base)

	mutations := map[string]func(s *OfflineSelection){
		"quantity":         func(s *OfflineSelection) { s.Lines[0].Quantity = 2 },
		"product sku":      func(s *OfflineSelection) { s.Lines[0].ProductSkuID = str("sku-2") },
		"menu sku":         func(s *OfflineSelection) { s.Lines[0].MenuProductSkuID = str("msku-1") },
		"line note":        func(s *OfflineSelection) { s.Lines[0].Note = str("no ice") },
		"topping quantity": func(s *OfflineSelection) { s.Lines[0].Toppings[0].Quantity = 3 },
		"topping sku":      func(s *OfflineSelection) { s.Lines[0].Toppings[0].ProductSkuID = "sku-t2" },
		"topping note":     func(s *OfflineSelection) { s.Lines[0].Toppings[0].Note = str("extra") },
		"extra topping": func(s *OfflineSelection) {
			s.Lines[0].Toppings = append(s.Lines[0].Toppings, OfflineSelectionTopping{ToppingGroupItemID: "tg-2", ProductSkuID: "sku-t3", Quantity: 1})
		},
		"extra line": func(s *OfflineSelection) {
			s.Lines = append(s.Lines, OfflineSelectionLine{LineID: "line-2", ProductSkuID: str("sku-9"), Quantity: 1})
		},
		"order type":          func(s *OfflineSelection) { s.OrderType = "takeaway" },
		"pickup type":         func(s *OfflineSelection) { s.PickupType = "scheduled" },
		"scheduled pickup at": func(s *OfflineSelection) { s.ScheduledPickupAt = str("2026-07-26T12:00:00Z") },
		"customer":            func(s *OfflineSelection) { s.CustomerID = str("cust-1") },
		"guest count":         func(s *OfflineSelection) { s.GuestCount = num(4) },
		"tables":              func(s *OfflineSelection) { s.TableIDs = []string{"t-1"} },
		"locale":              func(s *OfflineSelection) { s.Locale = "vi" },
		"channel":             func(s *OfflineSelection) { s.Channel = "kiosk" },
		"device":              func(s *OfflineSelection) { s.DeviceID = str("dev-1") },
		"coupon":              func(s *OfflineSelection) { s.CouponCode = str("SAVE10") },
		"split mode":          func(s *OfflineSelection) { s.SplitMode = str("by_people") },
		"split people":        func(s *OfflineSelection) { s.SplitPeopleCount = num(2) },
		"order note":          func(s *OfflineSelection) { s.Note = str("VIP") },
	}

	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			mutated := base
			// Deep-copy the slices the mutation may touch.
			mutated.Lines = append([]OfflineSelectionLine(nil), base.Lines...)
			mutated.Lines[0].Toppings = append([]OfflineSelectionTopping(nil), base.Lines[0].Toppings...)
			mutate(&mutated)

			if OfflineSelectionDigest(mutated) == baseDigest {
				t.Errorf("changing %s left the digest unchanged — that field is unsigned and forgeable", name)
			}
		})
	}
}

// TestOfflineSigning_NoteDelimiterCannotForgeAFieldBoundary — a note containing
// the delimiter (or the absent marker) must not be able to impersonate another
// field. This is why free text is hashed rather than embedded.
func TestOfflineSigning_NoteDelimiterCannotForgeAFieldBoundary(t *testing.T) {
	str := func(s string) *string { return &s }
	line := func(note string) OfflineSelection {
		return OfflineSelection{
			Lines:      []OfflineSelectionLine{{LineID: "line-1", ProductSkuID: str("sku-1"), Quantity: 1, Note: str(note)}},
			OrderType:  "dine_in",
			PickupType: "immediate",
			Locale:     "ja",
			Channel:    "workstation",
		}
	}

	// An attacker-controlled note trying to inject fields/records.
	injected := OfflineSelectionDigest(line("x\n2\n~\nL\nline-2\n~\nsku-9\n99\n~\n0"))
	plain := OfflineSelectionDigest(line("x"))
	empty := OfflineSelectionDigest(line(""))
	marker := OfflineSelectionDigest(line("~"))

	if injected == plain {
		t.Error("an injected note produced the same digest as a plain note")
	}
	// An EMPTY note and a literal "~" note must not collide either — the marker
	// is only meaningful as an absence, and a customer could literally type "~".
	if empty == marker {
		t.Error(`empty note and a literal "~" note collide — the absent marker is forgeable`)
	}
}

// TestOfflineSigning_SignAndVerifyRoundTrip — a real Ed25519 round trip, plus
// the rejections Cloud will perform.
func TestOfflineSigning_SignAndVerifyRoundTrip(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(nil)
	if err != nil {
		t.Fatalf("keygen: %v", err)
	}
	pubB64 := encodeBase64(pub)

	sel := OfflineSelection{
		Lines:      []OfflineSelectionLine{{LineID: "line-1", ProductSkuID: strPtr("sku-1"), Quantity: 2}},
		OrderType:  "takeaway",
		PickupType: "immediate",
		Locale:     "ja",
		Channel:    "workstation",
	}
	env := OfflineEvidenceEnvelope{
		DeviceID: "dev-1", IssuerID: "iss-1", CatalogRevision: 12,
		IssuedAt: "2026-07-26T10:00:00Z", ExpiresAt: "2026-07-29T10:00:00Z", KeyID: "key-1",
	}

	sig, digest, err := SignOfflineOrder(priv, env, sel)
	if err != nil {
		t.Fatalf("sign: %v", err)
	}
	if digest != OfflineSelectionDigest(sel) {
		t.Error("returned digest is not the digest that was signed")
	}
	if !VerifyOfflineSignature(pubB64, sig, OfflineSigningMessage(env, digest)) {
		t.Fatal("a freshly signed message failed verification")
	}

	t.Run("a tampered quantity breaks the signature", func(t *testing.T) {
		tampered := sel
		tampered.Lines = append([]OfflineSelectionLine(nil), sel.Lines...)
		tampered.Lines[0].Quantity = 99
		if VerifyOfflineSignature(pubB64, sig, OfflineSigningMessage(env, OfflineSelectionDigest(tampered))) {
			t.Error("signature still verified after the order was rewritten")
		}
	})

	t.Run("a tampered catalog revision breaks the signature", func(t *testing.T) {
		other := env
		other.CatalogRevision = 13
		if VerifyOfflineSignature(pubB64, sig, OfflineSigningMessage(other, digest)) {
			t.Error("signature still verified after the claimed catalog changed")
		}
	})

	t.Run("another device's key does not verify", func(t *testing.T) {
		otherPub, _, _ := ed25519.GenerateKey(nil)
		if VerifyOfflineSignature(encodeBase64(otherPub), sig, OfflineSigningMessage(env, digest)) {
			t.Error("a foreign public key verified this signature")
		}
	})

	t.Run("malformed inputs are clean rejections, not panics", func(t *testing.T) {
		msg := OfflineSigningMessage(env, digest)
		for name, args := range map[string][2]string{
			"garbage signature": {"!!!not-base64!!!", pubB64},
			"short signature":   {encodeBase64([]byte("too short")), pubB64},
			"garbage key":       {sig, "!!!not-base64!!!"},
			"short key":         {sig, encodeBase64([]byte("short"))},
			"empty both":        {"", ""},
		} {
			if VerifyOfflineSignature(args[1], args[0], msg) {
				t.Errorf("%s verified — must fail closed", name)
			}
		}
	})

	t.Run("signing with a malformed key errors instead of producing garbage", func(t *testing.T) {
		if _, _, err := SignOfflineOrder(ed25519.PrivateKey("too short"), env, sel); err == nil {
			t.Error("expected an error for a malformed private key")
		}
	})
}

func strPtr(s string) *string { return &s }
